import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {once} from 'node:events';
import {WebSocket,WebSocketServer} from 'ws';
import {createGateway} from './server.mjs';
import {validateConfig} from './config.mjs';

test('actual default Technical Chart figure crosses the real upstream parser and gateway relay',{timeout:5000},async t=>{
  // Generated by actual app.ta.payload.build_payload:250 daily OHLCV bars,
  // ChartParams(symbol='AAPL',interval='1d',macro='classic-momentum').
  const figure=await readFile(new URL('./test-fixtures/ta-default-250-daily.json',import.meta.url));
  assert.equal(figure.length,77371);assert.equal(JSON.parse(figure).type,'figure');
  const source=new WebSocketServer({host:'127.0.0.1',port:0});await once(source,'listening');
  t.after(()=>new Promise(resolve=>{for(const c of source.clients)c.terminate();source.close(resolve);}));
  const origin=`https://openbq.${['example-tailnet','ts','net'].join('.')}:10000`,token='synthetic_test_credential_not_for_deployment';
  const config=validateConfig({origin,liveGrid:true},{token,apiUsername:'test',apiPassword:'test'});
  const gateway=createGateway({...config,gridOrigin:`http://127.0.0.1:${source.address().port}`});
  gateway.listen(0,'127.0.0.1');await once(gateway,'listening');t.after(()=>gateway.closeGateway());
  const upstream=once(source,'connection');
  const client=new WebSocket(`ws://127.0.0.1:${gateway.address().port}/grid/ta_chart_ws?symbol=AAPL&interval=1d&macro=classic-momentum`,{headers:{Host:new URL(origin).host,Origin:origin,Authorization:`Bearer ${token}`}});
  client.on('error',()=>{});t.after(()=>client.terminate());
  const [producer]=await upstream;
  const delivered=once(client,'message');producer.send(figure,{binary:false});const [actual]=await delivered;assert.deepEqual(actual,figure);
  const closed=once(client,'close');producer.send('x'.repeat(8*1024*1024+1));await closed;
});
